-- Filled by the assembler with exact URL-to-file mappings.
offline_http = {state={ok=200, no_response=204, timed_out=408, too_large=413, unknown=0}}
local pending_asset_requests = {}
local next_asset_request = 0
local function response_success(self) return self.status == 200 end
function offline_http:request(method, url, options, callback)
    if type(options) == 'function' and callback == nil then callback, options = options, {} end
    assert(type(callback) == 'function', 'emberlash: asset request requires a callback')
    next_asset_request = next_asset_request + 1
    local id = next_asset_request
    local asset = offline_asset_files[url]
    local response = {status=503, body=nil, headers={}, success=response_success, offline=true}
    if asset and method == 'GET' then
        local body = readfile(asset.path)
        assert(body and #body == asset.bytes, 'emberlash: missing or damaged asset ' .. asset.path)
        response.status, response.body = 200, body
        response.headers['content-length'] = tostring(#body)
        response.headers['content-type'] = asset.mime
    else
        response.error = 'Cloud service unavailable in offline build'
    end
    pending_asset_requests[id] = true
    client.delay_call(0, function()
        if not pending_asset_requests[id] then return end
        pending_asset_requests[id] = nil
        local ok, message = pcall(callback, response)
        if not ok then client.error_log('emberlash asset callback: ' .. tostring(message)) end
    end)
    return id
end
function offline_http:cancel(id)
    local exists = pending_asset_requests[id] ~= nil
    pending_asset_requests[id] = nil
    return exists
end

-- The range registry retains ownership after restoration. Reuse that owner
-- when the prediction observer is enabled again.
function install_prediction_observer_hook(state, patcher)
    local hook = state.hook
    if hook == nil then
        return patcher.jump_hook(state.site, state.cave_address, state.hook_size, true)
    end
    assert(tonumber(hook.base) == tonumber(state.site),
        "prediction-error observer patch owner address changed")
    return hook:jump_hook(0, state.cave_address, state.hook_size, true)
end

