                                                                                                                                                                                                            tbl_70.experimental_inverter_params = tbl_29.default_config()
                                                                                                                                                                                                            local function fn_144(a_2, b)
                                                                                                                                                                                                                local default_config = tbl_29.default_config(tbl_70.experimental_inverter_params)
                                                                                                                                                                                                                if a_2 == nil then
                                                                                                                                                                                                                    return default_config
                                                                                                                                                                                                                end
                                                                                                                                                                                                                for k_2, v in pairs(a_2) do
                                                                                                                                                                                                                    if k_2 ~= "_use_enemy_ping" then
                                                                                                                                                                                                                        default_config[k_2] = v
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                                if not a_2._use_enemy_ping then
                                                                                                                                                                                                                    return default_config
                                                                                                                                                                                                                end
                                                                                                                                                                                                                default_config.enemy_ping = b
                                                                                                                                                                                                                return default_config
                                                                                                                                                                                                            end
                                                                                                                                                                                                            fn_145 = function(a_2, b)
                                                                                                                                                                                                                local v = fn_140()
                                                                                                                                                                                                                local v_2 = a_2
                                                                                                                                                                                                                local lower_2 = v_2.lower(v_2)
                                                                                                                                                                                                                local gsub = lower_2.gsub(lower_2, "^%l", string.upper)
                                                                                                                                                                                                                local v_61 = tbl_81.cheat.Experimental[gsub]
                                                                                                                                                                                                                if v_61 ~= nil and v_61[v] ~= nil then
                                                                                                                                                                                                                    return fn_144(v_61[v], b)
                                                                                                                                                                                                                end
                                                                                                                                                                                                                return fn_144(v_61, b)
                                                                                                                                                                                                            end
                                                                                                                                                                                                            tbl_70.height_advantage_cache = {command = -1, target = nil, state = nil, value = false}
                                                                                                                                                                                                            tbl_70.is_height_advantage = function(a_2)
                                                                                                                                                                                                                local v = v_27()
                                                                                                                                                                                                                local command_target = tbl_70.get_command_target()
                                                                                                                                                                                                                local state = tbl_27.state
                                                                                                                                                                                                                local safe_head_height_states = val.addons.safe_head_height_states
                                                                                                                                                                                                                if v ~= nil and command_target ~= nil and v_28(command_target) and not v_32(command_target) and safe_head_height_states ~= nil and safe_head_height_states:get(state) then
                                                                                                                                                                                                                    local cond = a_2 ~= nil and (a_2.command_number or v_35()) or v_35()
                                                                                                                                                                                                                    if tbl_70.height_advantage_cache.command == cond and tbl_70.height_advantage_cache.target == command_target and tbl_70.height_advantage_cache.state == state then
                                                                                                                                                                                                                        return tbl_70.height_advantage_cache.value
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    local ret, ret_2, ret_3 = v_30(v)
                                                                                                                                                                                                                    local ret_4, ret_2_2, ret_3_2 = v_30(command_target)
                                                                                                                                                                                                                    if ret ~= nil and ret_4 ~= nil then
                                                                                                                                                                                                                        local _, _, ret_3_3 = v_29(v, 0)
                                                                                                                                                                                                                        local _, _, ret_3_4 = v_29(command_target, 0)
                                                                                                                                                                                                                        local v_2 = ret_3_3
                                                                                                                                                                                                                        if not v_2 then
                                                                                                                                                                                                                            local cond_2 = ret_3 or 0
                                                                                                                                                                                                                            v_2 = cond_2 + 64
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        local v_61 = v_2
                                                                                                                                                                                                                        local v_1754 = ret_3_4
                                                                                                                                                                                                                        if not v_1754 then
                                                                                                                                                                                                                            local cond_9 = ret_3_2 or 0
                                                                                                                                                                                                                            v_1754 = cond_9 + 64
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        local v_1755 = v_1754
                                                                                                                                                                                                                        local val_13 = ret_4 - ret
                                                                                                                                                                                                                        local val_40 = ret_2_2 - ret_2
                                                                                                                                                                                                                        local v_1756 = v_25(val_13 * val_13 + val_40 * val_40)
                                                                                                                                                                                                                        local cond_10 = state == "In air" or state == "In air-duck"
                                                                                                                                                                                                                        local val_41 = 42 + v_20(18, v_1756 * 0.015)
                                                                                                                                                                                                                        local cond_11 = cond_10 and 14 or 0
                                                                                                                                                                                                                        local val_42 = val_41 + cond_11
                                                                                                                                                                                                                        local cond_12 = ret_3 or 0
                                                                                                                                                                                                                        local cond_13 = ret_3_2 or 0
